import pytest
from solution import merge_intervals


def test_empty_list():
    assert merge_intervals([]) == []


def test_single_interval():
    assert merge_intervals([[1, 3]]) == [[1, 3]]


def test_no_overlap_sorted():
    assert merge_intervals([[1, 2], [3, 4], [5, 6]]) == [[1, 2], [3, 4], [5, 6]]


def test_no_overlap_unsorted():
    assert merge_intervals([[5, 6], [1, 2], [3, 4]]) == [[1, 2], [3, 4], [5, 6]]


def test_all_overlapping():
    assert merge_intervals([[1, 3], [2, 6], [8, 10], [15, 18]]) == [[1, 6], [8, 10], [15, 18]]


def test_touching_intervals_merge():
    assert merge_intervals([[1, 4], [4, 5]]) == [[1, 5]]


def test_contained_interval():
    assert merge_intervals([[1, 10], [2, 3], [4, 5]]) == [[1, 10]]


def test_negative_intervals():
    assert merge_intervals([[-10, -5], [-7, -1], [0, 2]]) == [[-10, -1], [0, 2]]


def test_duplicate_intervals():
    assert merge_intervals([[1, 4], [1, 4], [1, 4]]) == [[1, 4]]


def test_unsorted_overlapping():
    assert merge_intervals([[8, 10], [1, 3], [2, 6], [15, 18]]) == [[1, 6], [8, 10], [15, 18]]


def test_large_values():
    assert merge_intervals([[1000000, 2000000], [1500000, 2500000]]) == [[1000000, 2500000]]


def test_zero_length_interval():
    assert merge_intervals([[1, 1], [1, 2]]) == [[1, 2]]


def test_input_not_modified():
    intervals = [[1, 3], [2, 4]]
    merge_intervals(intervals)
    assert intervals == [[1, 3], [2, 4]]



def test_same_start_different_end():
    assert merge_intervals([[1, 5], [1, 3], [1, 4]]) == [[1, 5]]

def test_contained_interval_end_less_than_last():
    assert merge_intervals([[1, 10], [2, 5], [6, 8]]) == [[1, 10]]
